    "理想气体": "Ideal gas",
    "不可压缩": "Incompressible",
    "理想气体：SU2 按可压缩 Navier–Stokes（无黏时为 Euler）方程求解，状态方程 p = ρRT；参考压力在流固耦合设置中给定，密度由参考压力和温度确定。": "Ideal gas: SU2 solves the compressible Navier–Stokes equations (Euler when inviscid) with p = ρRT. The reference pressure is set in the FSI settings; density follows from the reference pressure and temperature.",
    "不可压缩：SU2 按常密度不可压缩 Navier–Stokes 方程求解，压力为相对出口（参考）压力的表压。体积模量与声速仅作记录。": "Incompressible: SU2 solves the constant-density incompressible Navier–Stokes equations; pressure is gauge pressure relative to the outlet (reference). Bulk modulus and speed of sound are recorded only.",
