    "帽盖硬化模量 dPb/dεv (MPa，0 不硬化)": "Cap hardening modulus dPb/dεv (MPa, 0 = no hardening)",
    "同一计算只能加载一个 OpenCourant 用户材料库。": "One run can load only one OpenCourant user material library.",
    "项目内缺少 RHT 用户材料库 third_party/opencourant/userlib-rht/libraduser_win64.dll。": "The RHT user material library third_party/opencourant/userlib-rht/libraduser_win64.dll is missing from the project.",
    "损伤塑性本构 · OpenCourant 显式准静态": "Damage plasticity laws · OpenCourant explicit quasi-static",
    "OpenCourant：平面应变单层薄片（每个三角形剖分为 3 个六面体），显式积分 + 自适应动力松弛（/ADYREL）按线性加载求准静态解。所有材料须选择“OpenCourant 本构”卡，可选 RHT、CDPM2、JH2、HJC、Drucker–Prager（含帽盖）、Johnson–Cook 等；应变率增强在准静态计算中关闭。软化材料建议用位移控制。": "OpenCourant: a plane-strain one-layer slab (each triangle becomes 3 hexahedra), explicit integration and adaptive dynamic relaxation (/ADYREL) under a linear load ramp give the quasi-static solution. Every material needs an “OpenCourant material law” card: RHT, CDPM2, JH2, HJC, Drucker–Prager (with cap), Johnson–Cook and others; strain-rate enhancement is switched off in quasi-static runs. Use displacement control for softening materials.",
    "准静态加载时长系数（× 模型尺寸 / 纵波速）": "Quasi-static ramp duration factor (× model size / P-wave speed)",
    "准静态加载时长系数": "Quasi-static ramp duration factor",
    "准静态加载时长系数须在 10–10000 之间。": "The quasi-static ramp duration factor must be between 10 and 10000.",
    "OpenCourant 本构（RHT / CDPM2 / JH2 / HJC / DP / Johnson–Cook）": "OpenCourant law (RHT / CDPM2 / JH2 / HJC / DP / Johnson–Cook)",
    "OpenCourant 材料模型": "OpenCourant material model",
    "OpenCourant 本构损伤 D 由材料自身演化（RHT、CDPM2、JH2、HJC），参与刚度与强度退化；Drucker–Prager、Johnson–Cook 等输出等效塑性应变。可选的拉伸应变失效、RHT 侵蚀应变或 Johnson–Cook εp,max 会删除单元。": "The OpenCourant constitutive damage D evolves inside the material law (RHT, CDPM2, JH2, HJC) and degrades stiffness and strength; Drucker–Prager, Johnson–Cook and others report equivalent plastic strain. The optional tensile strain failure, the RHT erosion strain or the Johnson–Cook εp,max delete elements.",
    "显式积分采用更新拉格朗日有限变形格式。加载按线性斜坡施加，自适应动力松弛消除惯性；结果给出加载结束时动能与内能之比，超过 5% 时提示加长加载时长。损伤为连续损伤带，没有离散裂面接触。": "The explicit integration uses an updated-Lagrangian finite-deformation formulation. Loads follow a linear ramp and adaptive dynamic relaxation removes inertia; the result reports the kinetic-to-internal energy ratio at the end of the ramp and asks for a longer ramp above 5%. Damage forms continuous bands without discrete crack contact.",
    "复用结构中的三角形网格：每个三角形剖分为 3 个四边形并拉伸为一层六面体薄片（平面应变，全部节点约束面外位移）。单位：m、N、Pa；载荷按单位厚度换算。加载增量数即保存的结果帧数（不超过 200）。": "Reuses the structure's triangle mesh: each triangle is split into 3 quadrilaterals and extruded into a one-layer hexahedral slab (plane strain, out-of-plane displacement fixed at every node). Units: m, N, Pa; loads are per unit thickness. The load increments are the saved result frames (at most 200).",
    "本构损伤 D（0–1，OpenCourant）": "Constitutive damage D (0–1, OpenCourant)",
    "OpenCourant 本构损伤参与刚度与强度退化；损伤带为连续单元损伤，不是张开的离散裂面。": "OpenCourant constitutive damage degrades stiffness and strength; damage bands are continuous element damage, not open discrete cracks.",
    "OpenCourant 本构损伤参与刚度与强度退化；应力与应变为子单元的面积平均。": "OpenCourant constitutive damage degrades stiffness and strength; stress and strain are area averages of the sub-elements.",
    "OpenCourant 单元应力、应变、塑性应变与本构损伤取三个子单元的面积平均。": "OpenCourant element stress, strain, plastic strain and constitutive damage are area averages of the three sub-elements.",
    "OpenCourant 正在进行显式准静态求解…": "OpenCourant is running the explicit quasi-static analysis…",
    "OpenCourant · TETRA4 · 显式准静态（自适应动力松弛）": "OpenCourant · TETRA4 · explicit quasi-static (adaptive dynamic relaxation)",
    "OpenCourant 本构（RHT、CDPM2、JH2、HJC、Drucker–Prager、Johnson–Cook 等）按线性加载斜坡显式积分，自适应动力松弛消除惯性；增量数即结果帧数（不超过 200），应变率增强在准静态计算中关闭。软化材料建议用位移控制。": "OpenCourant laws (RHT, CDPM2, JH2, HJC, Drucker–Prager, Johnson–Cook and others) are integrated explicitly under a linear load ramp with adaptive dynamic relaxation; the increments are the result frames (at most 200) and strain-rate enhancement is switched off. Use displacement control for softening materials.",
    "OpenCourant 准静态计算要求所有体域使用 OpenCourant 本构卡。": "The OpenCourant quasi-static analysis needs an OpenCourant material card on every volume.",
    "OpenCourant 准静态路径需要选择 OpenCourant 求解器。": "The OpenCourant quasi-static path needs the OpenCourant solver.",
    "OpenCourant 二维损伤变形按平面应变单层薄片计算，请选择平面应变。": "The 2D OpenCourant analysis is a plane-strain slab; choose plane strain.",
    "OpenCourant 损伤变形最多支持 20 万节点 / 40 万单元。": "The OpenCourant deformation analysis supports up to 200,000 nodes / 400,000 elements.",
    "OpenCourant 准静态路径的结果帧数（加载增量数）须不超过 200。": "The OpenCourant quasi-static path saves at most 200 result frames (load increments).",
    "OpenCourant 准静态路径要求所有实体材料选择 OpenCourant 本构卡，不与 CalculiX 本构混算。": "The OpenCourant quasi-static path needs an OpenCourant material law on every solid material; it is not mixed with CalculiX laws.",
