    "仅回放已收敛增量，按载荷比例推进；这是准静态加载过程，不是真实动力时间。": "Replays converged increments at a rate based on load fraction. This is quasi-static loading, not physical dynamic time.",
    "回放准静态加载增量，非瞬态动力时间。": "Replays quasi-static load increments, not transient dynamic time.",
