    "J2 塑性 · 线性各向同性硬化": "J2 plasticity · linear isotropic hardening",
    "弹性 · 可启用几何非线性": "Elasticity · optional geometric nonlinearity",
    "平面应力 · 单位厚度": "Plane stress · unit thickness",
    "平面应变 · 单位厚度": "Plane strain · unit thickness",
    "有限变形 / 几何非线性": "Finite deformation / geometric nonlinearity",
    "塑性硬化模量 dσ/dεp (MPa)": "Plastic hardening modulus dσ/dεp (MPa)",
    "损伤起始等效塑性应变": "Equivalent plastic strain at damage initiation",
    "按材料分别设置本构、屈服应力、硬化模量和损伤起始阈值。同一材料的区域共享该材料参数，各材料之间独立。E、ν 沿用各区域材料属性。": "Set the constitutive model, yield stress, hardening modulus and damage initiation threshold for each material. Regions with the same material share its settings; different materials remain independent. E and ν come from the region material properties.",
    "请先为实体区域分配材料。": "Assign materials to solid regions first.",
    "加载与收敛": "Loading and convergence",
    "最终载荷系数": "Final load factor",
    "初始加载增量数": "Initial number of load increments",
    "最大允许增量数": "Maximum number of increments",
    "按比例缓慢施加结构中的节点力、分布力及体力等效载荷。固定约束沿用几何设置。非收敛结果不作为完整结果发布。": "Ramp up nodal forces and equivalent distributed and body loads proportionally. Fixed constraints follow the geometry settings. Unconverged runs are not published as complete results.",
    "模型与网格": "Model and mesh",
    "网格节点上限": "Mesh node limit",
    "生成 / 更新实体网格": "Generate / update solid mesh",
    "共享结构几何、材料及三角形网格，使用 CalculiX CPS3 / CPE3 单元。请在结构绘制中配置材料、约束与载荷。单位：m、N、Pa；厚度固定 1 m。": "Uses the shared geometry, materials and triangular mesh with CalculiX CPS3 / CPE3 elements. Configure materials, constraints and loads in Structure. Units: m, N, Pa; thickness is fixed at 1 m.",
    "损伤评估范围": "Scope of damage assessment",
    "当前提供 PEEQ / 起始阈值指标，达到 1 表示达到用户定义的塑性应变阈值。这是后处理评估，不参与本构积分；尚不提供损伤演化、刚度退化、单元删除或裂纹扩展。": "The PEEQ / initiation threshold indicator reaches 1 at the user-defined plastic strain threshold. This is post-processing only; it does not affect constitutive integration. Damage evolution, stiffness degradation, element deletion and crack growth are not available.",
    "有限变形应力为 Cauchy 应力，应变遵循 CalculiX 原生输出定义。等效塑性应变为外推到节点的场量。塑性与损伤指标只适用于 J2 塑性模型。": "Finite-deformation stresses are Cauchy stresses; strains follow CalculiX output definitions. Equivalent plastic strain is extrapolated to nodes. Plasticity and damage indicators apply only to J2 plastic materials.",
    "就绪。请先配置模型并生成网格。": "Ready. Configure the model and generate a mesh first.",
    "专业计算 / 独立结果": "Specialties / Separate results",
    "损伤变形结果": "Damage & Deformation Results",
    "查看收敛增量中的变形、应力与塑性应变。结果保留计算时的模型快照。": "Inspect deformation, stress and plastic strain at converged increments. Results retain a snapshot of the model used for the run.",
    "返回参数面板": "Back to setup",
    "导出结果 JSON": "Export results as JSON",
