    "请先运行计算。": "Run an analysis first.",
    "损伤变形结果云图": "Damage and deformation contour plot",
    "云图按三角形节点平均值着色；上方显示节点峰值。损伤起始指标不表示损伤演化或刚度退化。": "Triangles are colored by the mean of nodal values; the nodal maximum is shown above. Damage initiation does not represent damage evolution or stiffness degradation.",
