    "材料参数卡无效。": "Invalid material settings card.",
    "缺少材料的损伤变形参数。": "Damage and deformation settings are missing for a material.",
    "请先生成实体网格。": "Generate a solid mesh first.",
    "当前变形模块最多支持 20 万节点 / 40 万单元。": "The deformation module supports up to 200,000 nodes / 400,000 elements.",
    "最大允许增量数控制切步预算。大网格自动抽样保存已收敛结果，完整求解始终保存最终载荷帧。": "The maximum increment count sets the cutback budget. Large meshes save sampled converged frames. A completed solve always saves the final load frame.",
    "损伤变形材料库": "Deformation material library",
    "在基础材料库选择关联卡并保存材料。同一基础材料用于其他模型时会自动读取这张卡。": "Select a linked card in the base material library and save the material. Other models using that material automatically use the same card.",
