    "Mohr–Coulomb": "Mohr–Coulomb",
    "常比热比理想气体状态方程。": "Ideal gas equation of state with constant heat capacity ratio.",
    "JWL 状态方程，适用于已反应爆轰产物的膨胀。": "JWL equation of state for expansion of reacted detonation products.",
    "Noble–Abel 状态方程，考虑余容积；须满足 bρ < 1。": "Noble–Abel equation of state with covolume; requires bρ < 1.",
    "Stiffened Gas 状态方程，以压力偏置描述介质刚度。": "Stiffened Gas equation of state with a pressure offset.",
    "线弹性：各向同性弹性响应，不包含塑性和损伤。": "Linear elasticity: isotropic elastic response without plasticity or damage.",
    "JH2：压力相关强度、应变率、塑性损伤和破碎剩余强度。": "JH2: pressure-dependent strength, strain-rate effects, plastic damage and fractured strength.",
    "Mohr–Coulomb：压力相关剪切屈服、拉伸截断与可选应变软化；当前支持小变形平面应变。": "Mohr–Coulomb: pressure-dependent shear yield, tensile cutoff and optional strain softening; small-strain plane strain.",
    "Mohr–Coulomb：按平面应变匹配为 Drucker–Prager 锥（OpenCourant /MAT/DPRAG1），含拉伸截断；剪胀角、应变软化与残余强度不参与计算。": "Mohr–Coulomb: mapped to a plane-strain-matched Drucker–Prager cone (OpenCourant /MAT/DPRAG1) with tensile cutoff; dilation, softening and residual strength are not used.",
    "常比热比理想气体（OpenCourant /EOS/POLYNOMIAL，C4 = C5 = γ − 1）。": "Constant-γ ideal gas (OpenCourant /EOS/POLYNOMIAL, C4 = C5 = γ − 1).",
    "JWL 状态方程（OpenCourant /MAT/JWL），在炮孔中心点起爆，适用于爆轰产物膨胀。": "JWL EOS (OpenCourant /MAT/JWL), detonated at the borehole center, for expanding detonation products.",
    "请选择支持的状态方程（产物：JWL 或理想气体；间隙气体：理想气体）。": "Choose a supported EOS (products: JWL or ideal gas; gap gas: ideal gas).",
