    "静力强度准则": "Static strength criterion",
    "未完成校核单元": "Unchecked elements",
    "未完成校核（参数缺失或无效）": "Unchecked (missing or invalid parameters)",
    "第一强度理论 · 最大主应力（Rankine）": "I \u00b7 Maximum principal stress (Rankine)",
    "第二强度理论 · 最大主应变（Saint-Venant）": "II \u00b7 Maximum principal strain (Saint-Venant)",
    "第三强度理论 · 最大剪应力（Tresca）": "III \u00b7 Maximum shear stress (Tresca)",
    "第四强度理论 · 畸变能（von Mises）": "IV \u00b7 Distortion energy (von Mises)",
    "强度填写材料极限值（MPa）。当前按极限值直接校核，未施加设计安全系数；缺少所选准则参数时标为未完成校核。": "Enter material strength limits (MPa). Checks use these limits without a design safety factor. Missing criterion parameters are reported as unchecked.",
    "第一强度理论：比较三维主应力与抗拉、抗压强度；两项强度均须大于 0。": "Rankine: compare 3D principal stresses against tensile and compressive strengths; both must be positive.",
    "第二强度理论：比较主应变对应的 Eε 与抗拉、抗压强度，需要泊松比；阈值按单轴线弹性强度/E 换算。": "Saint-Venant: compare principal E*strain against tensile and compressive strengths using Poisson ratio; limits are converted from uniaxial strength/E.",
    "第三强度理论：最大主应力差与屈服强度比较；剪切屈服强度为屈服强度的 1/2。": "Tresca: compare the largest principal stress difference against yield strength; shear yield strength is yield strength/2.",
    "第四强度理论：von Mises 等效应力与屈服强度比较；剪切屈服强度为屈服强度的 1/√3。": "von Mises: compare equivalent stress against yield strength; shear yield strength is yield strength/sqrt(3).",

    "JWL": "JWL",
    "JH2": "JH2",
    "理想气体": "Ideal gas",
    "JH2 包含塑性损伤与破碎强度；当前仍采用二维连续网格，不包含碎块接触。气体模式从起爆后产物初态开始。": "JH2 includes plastic damage and fractured strength. The 2D continuum mesh does not include fragment contact. Gas mode starts from reacted products.",
    "所选本地本构已移除。请显式选择直接调用的 JH2，并填写完整参数卡。": "The selected local constitutive model was removed. Explicitly select upstream JH2 and provide its complete card.",
    "JH2 直接调用 OpenRadioss 材料核；Gf 不参与损伤，参考长度必须为0。": "JH2 directly calls the OpenRadioss material kernel; Gf does not enter damage and reference length must be zero.",
    "剪切模量 G (GPa，0 使用 E/ν)": "Shear modulus G (GPa; 0 uses E/nu)",
    "输入体积模量 K (GPa，仅记录，0 使用 E/ν)": "Input bulk modulus K (GPa; diagnostic only; 0 uses E/nu)",
    "损伤参考长度 (mm，当前仅支持0)": "Damage reference length (mm; only 0 supported)",
    "直接调用 LANL Singularity-EOS IdealGas；使用常比热比的密度-比内能接口。": "Direct LANL Singularity-EOS IdealGas density-energy interface with constant gamma.",
    "直接调用 LANL Singularity-EOS JWL；压力和体积模量由上游计算，内能为 J/kg。": "Direct LANL Singularity-EOS JWL pressure and bulk modulus; internal energy in J/kg.",
    "所选本地产物 EOS 已移除。请显式选择上游 JWL 或理想气体。": "The local products EOS was removed. Explicitly select upstream JWL or IdealGas.",
    "所选本地气体 EOS 已移除。请显式选择上游理想气体。": "The local gap gas EOS was removed. Explicitly select upstream IdealGas.",
    "归一化应力可直接填写 σHEL；填 0 时按 σHEL = 1.5 × (HEL − pHEL) 换算。EOS K1 控制初始体积刚度；β 须独立标定，当前参考长度必须为0。": "Enter sigmaHEL directly, or 0 to use 1.5 * (HEL - pHEL). K1 controls initial bulk stiffness; beta requires calibration; reference length must be zero.",
    "已移除：裂带拉伸损伤": "Removed: Crack-band tensile damage",
