    "拉伸损伤需要每种岩石的单轴抗拉强度。以下数值单位为 MPa；填写后运行时保存到材料库，不重新划分网格。": "Tensile damage requires each rock's uniaxial tensile strength in MPa. Values are saved to the material library when running; the mesh is retained.",
