    "专业计算 / 结构动力学": "Specialty / Structural Dynamics",
    "专业计算 / 结构动力学结果": "Specialty / Structural Dynamics Results",
    "模态、谐响应、瞬态与碰撞冲击：隐式分析由 CalculiX 求解，显式碰撞由 OpenCourant 求解。": "Modal, harmonic, transient and impact analyses: CalculiX solves the implicit analyses and OpenCourant the explicit impacts.",
