    "外力功": "External work",
    "沙漏能": "Hourglass energy",
    "X 向": "X direction", "Y 向": "Y direction", "Z 向": "Z direction",
    "求解结构固有频率、振型、参与因子与有效质量（Lanczos / ARPACK）。不需要外载荷；约束不足（自由–自由）时自动多求刚体模态并单独标注。": "Computes natural frequencies, mode shapes, participation factors and effective masses (Lanczos / ARPACK). No loads are needed; for insufficient restraints (free–free) the rigid-body modes are added and marked.",
    "在模态基础上做稳态简谐响应：模型中的载荷作为简谐力幅值，按频率扫描给出位移幅值、相位和应力幅值，以及频响曲线。": "Steady-state harmonic response on the modal basis: the model loads are harmonic force amplitudes, and a frequency sweep gives displacement amplitudes, phases, stress amplitudes and frequency-response curves.",
    "模态叠加法（快速，线性结构）或直接积分（α 法，无条件稳定）。模型载荷按选定时程变化，可设瑞利阻尼，适合冲击载荷、启停与强迫振动的时域响应。": "Mode superposition (fast, linear structures) or direct integration (α method, unconditionally stable). The model loads follow the chosen history with optional Rayleigh damping, for impact loads, start-up/shut-down and forced vibration in the time domain.",
    "模态叠加法（推荐，线性结构快速）": "Mode superposition (recommended; fast for linear structures)",
    "直接积分 α 法（完整矩阵）": "Direct α-method integration (full matrices)",
    "模态叠加法先求固有模态，再积分各阶模态方程，速度快，适合线弹性结构；参与叠加的模态应覆盖载荷频谱。直接积分用 α 法（无条件稳定）逐步求解完整方程。时间步宜不大于所关心最高频率周期的 1/20；可先做模态分析确定频率。": "Mode superposition extracts the natural modes and integrates the modal equations; it is fast and suits linear elastic structures, and the superposed modes should cover the load spectrum. Direct integration solves the full equations step by step with the α method (unconditionally stable). Keep the time step below 1/20 of the period of the highest frequency of interest; run a modal analysis first to find it.",
    "直接积分": "direct integration",
    "质量缩放最小时间步 (s，0 不缩放)": "Mass-scaling minimum time step (s; 0: none)",
    "中心差分显式积分，时间步由最小单元按稳定条件自动确定。网格中互不相连的部分自动识别为“部件”，部件之间需留出间隙。二维按平面应变单层薄片计算，能量与力按单位厚度给出。个别很小的单元会拖慢计算时，可设质量缩放最小时间步：程序只在这些单元的节点上增加质量，结果信息给出附加质量比例（宜小于 5%）。": "Central-difference explicit integration; the time step follows from the smallest element. Unconnected pieces of the mesh are detected as parts, and parts need a gap between them. 2D runs use a plane-strain slab, with energies and forces per unit thickness. When a few very small elements slow the run down, set a mass-scaling minimum time step: mass is added only at the nodes of those elements, and the run information reports the added mass ratio (keep it below 5%).",
    "注意：附加质量超过 5%，惯性被明显放大，冲击响应失真；请减小最小时间步或加粗网格。": "Note: the added mass exceeds 5%, so inertia is noticeably inflated and the impact response is distorted; lower the minimum time step or coarsen the mesh.",
    "最小时间步不能为负": "The minimum time step must not be negative",
    "最小时间步须小于计算时长": "The minimum time step must be shorter than the duration",
    "中心差分显式积分。各部件可设初速度，部件之间自动接触，可加刚性墙与重力，材料可为线弹性、双线性弹塑性或关联的 OpenCourant 本构卡。适合小球对撞、汽车撞墙、跌落等高速冲击。": "Central-difference explicit integration. Parts can have initial velocities and contact each other automatically, with optional rigid walls and gravity; materials can be linear elastic, bilinear plastic or a linked OpenCourant card. For ball collisions, car-to-wall crashes, drops and other high-speed impacts.",
    "二维显式动力学按平面应变单层薄片计算，请把二维假设设为平面应变。": "2D explicit dynamics uses a plane-strain slab; set the 2D assumption to plane strain.",
    "项目内缺少 CalculiX 求解器 third_party/calculix/bin/ccx.exe。": "The bundled CalculiX solver third_party/calculix/bin/ccx.exe is missing.",
    "谐响应分析需要模型中的载荷作为简谐力幅值，请在结构上施加载荷。": "Harmonic analysis uses the model loads as harmonic force amplitudes; apply loads to the structure.",
    "瞬态动力学需要模型中的载荷，请在结构上施加载荷（时程由载荷曲线给定）。": "Transient dynamics needs loads in the model; apply loads to the structure (the history sets their time variation).",
    "CalculiX 没有输出特征频率。": "CalculiX wrote no eigenfrequencies.",
    "CalculiX 振型输出不完整。": "The CalculiX mode-shape output is incomplete.",
    "CalculiX 没有输出谐响应结果。": "CalculiX wrote no harmonic-response results.",
    "CalculiX 没有输出瞬态结果。": "CalculiX wrote no transient results.",
    "CalculiX：刚度矩阵奇异，请检查约束与材料。": "CalculiX: the stiffness matrix is singular; check the restraints and materials.",
    "已选择施加外载荷，但模型中没有可施加的载荷。": "External loads were selected, but the model has no loads to apply.",
    "节点编号或坐标无效。": "Invalid node number or coordinates.",
    "关联的 OpenCourant 材料卡缺失": "The linked OpenCourant card is missing",
    "刚性墙法向不能为零向量": "The rigid-wall normal must not be zero",
    "刚性墙最多 8 个": "At most 8 rigid walls are allowed",
    "显式计算时长不能超过 10 s": "The explicit duration must not exceed 10 s",
    "扫频终点须大于起点": "The sweep end must exceed the sweep start",
    "时间步长不能大于计算时长": "The time step must not exceed the duration",
    "阻尼比须在 0–1 之间": "The damping ratio must be between 0 and 1",
    "瑞利阻尼系数不能为负": "Rayleigh coefficients must not be negative",
